import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.data = (ctypes.c_double * (rows * cols))()

    def __repr__(self):
        return f"GSLMatrix({self.rows}, {self.cols})"

    @property
    def ctypes_pointer(self):
        return ctypes.pointer(self.data)


def create_gsl_matrix(np_array):
    rows, cols = np_array.shape
    matrix = GSLMatrix(rows, cols)
    for i in range(rows):
        for j in range(cols):
            matrix.data[i * cols + j] = np_array[i, j]
    return matrix

def copy_matrix(dest, src):
    if dest.rows != src.rows or dest.cols != src.cols:
        return -1

    # Load the GSL library
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Define the function signature
    gsl.gsl_matrix_memcpy.argtypes = [ctypes.POINTER(ctypes.c_void_p), ctypes.POINTER(ctypes.c_void_p)]
    gsl.gsl_matrix_memcpy.restype = ctypes.c_int

    # Convert GSLMatrix to pointers
    dest_ptr = dest.ctypes_pointer
    src_ptr = src.ctypes_pointer

    # Call the function
    result = gsl.gsl_matrix_memcpy(dest_ptr, src_ptr)
    return result

