import numpy as np
import ctypes
import sys

class GSLMatrix:
    def __init__(self, rows, cols):
        self._matrix = ctypes.c_void_p()
        self._rows = rows
        self._cols = cols
        self._matrix = gsl.gsl_matrix_alloc(rows, cols)

    def __del__(self):
        if self._matrix:
            gsl.gsl_matrix_free(self._matrix)

    @property
    def matrix(self):
        return self._matrix

    @property
    def rows(self):
        return self._rows

    @property
    def cols(self):
        return self._cols


def numpy_to_gsl_matrix(np_array):
    if not isinstance(np_array, np.ndarray):
        raise ValueError("Input must be a numpy array")
    if np_array.ndim != 2:
        raise ValueError("Input must be a 2D numpy array")
    if np_array.dtype != np.float64:
        raise ValueError("Input must be of type float64")
    rows, cols = np_array.shape
    gsl_matrix = GSLMatrix(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl_matrix._matrix.contents.data[i * cols + j] = np_array[i, j]
    return gsl_matrix

def gsl_matrix_to_numpy(gsl_matrix):
    if not isinstance(gsl_matrix, GSLMatrix):
        raise ValueError("Input must be a GSLMatrix instance")
    np_array = np.zeros((gsl_matrix.rows, gsl_matrix.cols), dtype=np.float64)
    for i in range(gsl_matrix.rows):
        for j in range(gsl_matrix.cols):
            np_array[i, j] = gsl_matrix._matrix.contents.data[i * gsl_matrix.cols + j]
    return np_array


def main(jacobian, epsrel, n):
    try:
        jacobian_np = np.array(jacobian, dtype=np.float64)
        if jacobian_np.shape[0] != n or jacobian_np.shape[1] != n:
            raise ValueError(f"Jacobian dimensions {jacobian_np.shape} do not match n={n}")

        jacobian_gsl = numpy_to_gsl_matrix(jacobian_np)
        covar = GSLMatrix(n, n)
        status = gsl.gsl_multifit_covar(jacobian_gsl.matrix, ctypes.c_double(epsrel), covar.matrix)
        if status != 0:
            raise RuntimeError(f"GSL multifit covar failed with status {status}")

        covar_np = gsl_matrix_to_numpy(covar)
        return covar_np
    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

