class GSLMatrix:
    def __init__(self, rows, cols):
        self._matrix = ctypes.c_void_p()
        self._rows = rows
        self._cols = cols
        self._data = None

    def __del__(self):
        if self._matrix:
            gsl.gsl_matrix_free(ctypes.byref(self._matrix))

    def _get_data(self):
        if not self._data:
            self._data = np.ctypeslib.as_array(ctypes.cast(self._matrix, ctypes.POINTER(ctypes.c_double * self._cols)), shape=(self._rows, self._cols))
        return self._data

    def _set_data(self, data):
        self._data = data
        self._matrix = ctypes.pointer(ctypes.c_double * self._cols)(*data.flatten())

    data = property(_get_data, _set_data)

    def get_pointer(self):
        return self._matrix

    def get_rows(self):
        return self._rows

    def get_cols(self):
        return self._cols

    def to_numpy(self):
        return self.data

    @staticmethod
    def from_numpy(np_array):
        rows, cols = np_array.shape
        matrix = gsl.gsl_matrix_alloc(rows, cols)
        data = np_array.flatten().astype(np.float64)
        ctypes.memmove(ctypes.c_void_p(ctypes.addressof(ctypes.c_double * cols)(*data)), ctypes.c_void_p(matrix), ctypes.sizeof(ctypes.c_double) * rows * cols)
        return GSLMatrix(rows, cols)

