import ctypes
import numpy as np

class GSLFunction:
    def __init__(self, func):
        self.func = func

    def sample_function(self, x):
        return self.func(x)


def integrate_qk41(func, a, b):
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so", mode=ctypes.RTLD_GLOBAL)
    gsl_integration_qk41 = gsl.gsl_integration_qk41
    gsl_integration_qk41.argtypes = [ctypes.c_void_p, ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
    gsl_integration_qk41.restype = ctypes.c_int

    class gsl_function(ctypes.Structure):
        _fields_ = [('f', ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)), ('data', ctypes.c_void_p)]

    gsl_func = gsl_function(f=ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(lambda x: func(np.double(x))), data=None)

    result = ctypes.c_double(0.0)
    abs_error = ctypes.c_double(0.0)
    sum = ctypes.c_double(0.0)
    correction = ctypes.c_double(0.0)

    gsl_integration_qk41(ctypes.pointer(gsl_func), a, b, ctypes.pointer(result), ctypes.pointer(abs_error), ctypes.pointer(sum), ctypes.pointer(correction))

    return float(result), float(abs_error), float(sum), float(correction)


def test_integration():
    # Test case 1: f(x) = x^2 from 0 to 1
    def f1(x):
        return x * x
    result1, error1, sum1, correction1 = integrate_qk41(f1, 0.0, 1.0)
    print(f"Test 1: Result={result1}, Error={error1}, Sum={sum1}, Correction={correction1}")

    # Test case 2: f(x) = sin(x) from 0 to pi
    def f2(x):
        return np.sin(x)
    result2, error2, sum2, correction2 = integrate_qk41(f2, 0.0, np.pi)
    print(f"Test 2: Result={result2}, Error={error2}, Sum={sum2}, Correction={correction2}")

    # Test case 3: f(x) = exp(-x) from 0 to infinity
    def f3(x):
        return np.exp(-x)
    result3, error3, sum3, correction3 = integrate_qk41(f3, 0.0, 100.0)
    print(f"Test 3: Result={result3}, Error={error3}, Sum={sum3}, Correction={correction3}")

if __name__ == "__main__":
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    test_integration()

