class GSLPolyComplexWorkspace:
    def __init__(self, n):
        self.n = n
        self.workspace = ctypes.c_void_p()
        self.size = ctypes.c_size_t()
        self.func = None

    def create_workspace(self):
        self.func = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so").gsl_poly_complex_solve
        self.func.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.c_void_p]
        self.func.restype = ctypes.c_int

        self.size = ctypes.c_size_t(self.n + 1)
        self.workspace = ctypes.c_void_p()
        self.func(ctypes.pointer(ctypes.c_double(0)), self.n, ctypes.pointer(ctypes.c_double(0)), ctypes.pointer(ctypes.c_double(0)), ctypes.byref(self.workspace))

    def destroy_workspace(self):
        if self.workspace:
            ctypes.CDLL("/usr/local/gsl/lib/libgsl.so").gsl_poly_complex_solve_free(self.workspace)


def compute_complex_roots(coefficients):
    if not isinstance(coefficients, list) or not all(isinstance(c, float) for c in coefficients):
        raise ValueError("Input must be a list of floating-point numbers.")

    n = len(coefficients) - 1
    if n < 1:
        raise ValueError("Polynomial must have at least one root.")

    workspace = GSLPolyComplexWorkspace(n)
    workspace.create_workspace()

    roots_real = (ctypes.c_double * n)()
    roots_imag = (ctypes.c_double * n)()

    try:
        result = workspace.func(ctypes.cast(ctypes.pointer(ctypes.c_double(0)), ctypes.POINTER(ctypes.c_double)), n, roots_real, roots_imag, workspace.workspace)
        if result != 0:
            raise RuntimeError(f"Error calling gsl_poly_complex_solve: {result}")

        roots = [
            complex(roots_real[i], roots_imag[i])
            for i in range(n)
        ]
        return roots
    finally:
        workspace.destroy_workspace()

if __name__ == "__main__":
    coefficients = [1.0, 0.0, -1.0]
    roots = compute_complex_roots(coefficients)
    print(roots)

