import numpy as np

class GSLFunction:
    def __init__(self, func):
        self.func = func

    def callback(self, x):
        return self.func(x)

class GSLIntegrationWorkspace:
    def __init__(self):
        self.workspace = None

    def __del__(self):
        if self.workspace:
            self.workspace.release()

def f1(x):
    return x**2

def f2(x):
    return np.sin(x)

def f3(x):
    return np.exp(-x)

def integrate(function, a, b, epsabs, epsrel, limit, key):
    gsl_cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    gsl.gsl_integration_qag.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_int, ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
    gsl.gsl_integration_qag.restype = ctypes.c_int

    workspace = GSLIntegrationWorkspace()
    result = ctypes.c_double(0.0)
    error = ctypes.c_double(0.0)

    function_ptr = ctypes.c_void_p()
    function_obj = GSLFunction(function)
    function_callback = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(function_obj.callback)
    function_ptr = ctypes.cast(function_callback, ctypes.c_void_p)

    workspace.workspace = ctypes.pointer(ctypes.c_void_p())
    status = gsl.gsl_integration_qag(function_ptr, a, b, epsabs, epsrel, limit, key, workspace.workspace, ctypes.byref(result), ctypes.byref(error))

    if status != 0:
        raise Exception(f"Integration failed with status {status}")

    return result.value, error.value

