class GSLVector:
    def __init__(self, data):
        self.size = len(data)
        self.data = (ctypes.c_double * self.size)(*data)

    def get_data(self):
        return self.data

    def get_size(self):
        return self.size


def create_gsl_vector(data):
    return GSLVector(data)

def scaled_enorm(d, f):
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    gsl.scaled_enorm.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.c_int]
    gsl.scaled_enorm.restype = ctypes.c_double
    return gsl.scaled_enorm(d, f, f.contents.size)


def compute_scaled_enorm(vec1, vec2):
    try:
        if len(vec1) != len(vec2):
            raise ValueError("Vectors must be of the same length.")
        gsl_vec1 = create_gsl_vector(vec1)
        gsl_vec2 = create_gsl_vector(vec2)
        d = gsl_vec1.get_data()
        f = gsl_vec2.get_data()
        result = scaled_enorm(d, f)
        return float(result)
    except Exception as e:
        print(f"Error: {e}")
        return None

