class GSLMatrix:
    def __init__(self, size):
        self.size = size
        self.data = (ctypes.c_double * (size * size))()

    def get_data(self):
        return self.data

    def set_data(self, data):
        for i in range(self.size * self.size):
            self.data[i] = data[i]

    def get_size(self):
        return self.size


def matrix_to_gsl(matrix):
    size = len(matrix)
    gsl_matrix = GSLMatrix(size)
    flat_data = [element for row in matrix for element in row]
    gsl_matrix.set_data(flat_data)
    return gsl_matrix

def gsl_matrix_to_numpy(gsl_matrix):
    size = gsl_matrix.get_size()
    data = np.ctypeslib.as_array(gsl_matrix.get_data(), shape=(size, size))
    return data


def compute_matrix_exponential(matrix, mode):
    try:
        if not all(len(row) == len(matrix) for row in matrix):
            raise ValueError("Input matrix must be square.")

        size = len(matrix)
        gsl_matrix = matrix_to_gsl(matrix)
        gsl_matrix_data = gsl_matrix.get_data()

        # Load libraries
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

