import ctypes
import numpy as np

cdll_path_cblas = '/usr/local/gsl/lib/libgslcblas.so'
cdll_path_gsl = '/usr/local/gsl/lib/libgsl.so'

ctypes.CDLL(cdll_path_cblas, mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL(cdll_path_gsl)

# Define function signature for gsl_linalg_pcholesky_decomp
gsl.gsl_linalg_pcholesky_decomp.argtypes = [ctypes.POINTER(ctypes.POINTER(ctypes.c_double)), ctypes.POINTER(ctypes.c_int), ctypes.POINTER(ctypes.c_int)]
gsl.gsl_linalg_pcholesky_decomp.restype = ctypes.c_int

# Define function to create a gsl_matrix
def gsl_matrix_alloc(rows, cols):
    return gsl.gsl_matrix_alloc(ctypes.c_size_t(rows), ctypes.c_size_t(cols))

# Define function to create a gsl_permutation
def gsl_permutation_alloc(size):
    return gsl.gsl_permutation_alloc(ctypes.c_size_t(size))

# Define function to set a value in the matrix
def gsl_matrix_set(matrix, i, j, value):
    gsl.gsl_matrix_set(matrix, ctypes.c_size_t(i), ctypes.c_size_t(j), ctypes.c_double(value))

# Define function to get a value from the matrix
def gsl_matrix_get(matrix, i, j):
    return gsl.gsl_matrix_get(matrix, ctypes.c_size_t(i), ctypes.c_size_t(j))

# Define function to get a value from the permutation
def gsl_permutation_get(perm, i):
    return gsl.gsl_permutation_get(perm, ctypes.c_size_t(i))

# Define function to perform Cholesky decomposition
def cholesky_decomposition(input_matrix):
    rows = len(input_matrix)
    cols = len(input_matrix[0])

    # Allocate matrix and permutation
    mat = gsl_matrix_alloc(rows, cols)
    perm = gsl_permutation_alloc(rows)

    # Fill the matrix with input data
    for i in range(rows):
        for j in range(cols):
            gsl_matrix_set(mat, i, j, input_matrix[i][j])

    # Perform LDLT decomposition
    status = gsl.gsl_linalg_pcholesky_decomp(mat, perm, ctypes.c_int(1))

    if status != 0:
        raise ValueError(f"Cholesky decomposition failed with status {status}")

    # Extract the modified matrix
    result_matrix = [[0.0 for _ in range(cols)] for _ in range(rows)]
    for i in range(rows):
        for j in range(cols):
            result_matrix[i][j] = gsl_matrix_get(mat, i, j)

    # Extract the permutation vector
    perm_vector = [0 for _ in range(rows)]
    for i in range(rows):
        perm_vector[i] = gsl_permutation_get(perm, i)

    # Free memory
    gsl.gsl_matrix_free(mat)
    gsl.gsl_permutation_free(perm)

    return (result_matrix, perm_vector)

