class gsl_rng:
    def __init__(self, type_name):
        self._type = type_name
        self._ptr = ctypes.c_void_p()
        self._init = None
        self._free = None
        self._rng = None

        if self._type == 'mt19937':
            self._init = ctypes.CDLL(None).gsl_rng_set_seed
            self._free = ctypes.CDLL(None).gsl_rng_free
            self._rng = ctypes.CDLL(None).gsl_rng_mt19937
        elif self._type == 'taus2':
            self._init = ctypes.CDLL(None).gsl_rng_set_seed
            self._free = ctypes.CDLL(None).gsl_rng_free
            self._rng = ctypes.CDLL(None).gsl_rng_taus2
        else:
            raise ValueError(f'Unknown RNG type: {self._type}')

        self._ptr = self._rng()
        self._init.argtypes = [ctypes.c_void_p, ctypes.c_ulonglong]
        self._init.restype = None
        self._free.argtypes = [ctypes.c_void_p]
        self._free.restype = None
        self._rng.argtypes = []
        self._rng.restype = ctypes.c_void_p

    def set_seed(self, seed):
        self._init(self._ptr, seed)

    def free(self):
        self._free(self._ptr)

    def rand(self):
        return ctypes.CDLL(None).gsl_rng_get(self._ptr)

