import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, data):
        self.n = len(data)
        self.data = np.array(data, dtype=np.float64)
        self.size = self.n * self.n
        self.ptr = ctypes.c_void_p()
        self._create_gsl_matrix()

    def _create_gsl_matrix(self):
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        gsl.gsl_matrix_view_array.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.c_int, ctypes.c_int]
        gsl.gsl_matrix_view_array.restype = ctypes.c_void_p
        self.ptr = gsl.gsl_matrix_view_array(self.data.ctypes.data_as(ctypes.POINTER(ctypes.c_double)), self.n, self.n, self.n)

    def _get_gsl_matrix(self):
        return self.ptr

    def _free_gsl_matrix(self):
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        gsl.gsl_matrix_free.argtypes = [ctypes.POINTER(ctypes.c_void_p)]
        gsl.gsl_matrix_free(self.ptr)

    @staticmethod
    def is_positive_definite(matrix):
        mat = GSLMatrix(matrix)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        gsl.gsl_linalg_cholesky_decomp.argtypes = [ctypes.POINTER(ctypes.c_void_p)]
        try:
            gsl.gsl_linalg_cholesky_decomp(mat._get_gsl_matrix())
            return True
        except:
            return False

    def cholesky_decomp(self):
        if not GSLMatrix.is_positive_definite(self.data):
            raise ValueError("Matrix is not positive definite.")
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        gsl.gsl_linalg_cholesky_decomp.argtypes = [ctypes.POINTER(ctypes.c_void_p)]
        gsl.gsl_linalg_cholesky_decomp(self._get_gsl_matrix())
        result = np.zeros((self.n, self.n))
        for i in range(self.n):
            for j in range(self.n):
                if i >= j:
                    result[i][j] = self.data[i * self.n + j]
                else:
                    result[i][j] = 0.0
        self._free_gsl_matrix()
        return result.tolist()

