import ctypes
import sys

class GslSfResult:
    def __init__(self, value, error):
        self.value = value
        self.error = error

    def __str__(self):
        return f"({self.value}, {self.error})"


def compute_bessel_j0(x):
    try:
        # Load the GSL libraries in the recommended order
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError as e:
        raise RuntimeError(f"Failed to load GSL libraries: {e}") from e

    # Define the function signature for gsl_sf_bessel_J0_e
    gsl.gsl_sf_bessel_J0_e.argtypes = [ctypes.c_double, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
    gsl.gsl_sf_bessel_J0_e.restype = ctypes.c_int

    # Prepare output variables
    result = ctypes.c_double()
    error = ctypes.c_double()

    # Call the GSL function
    status = gsl.gsl_sf_bessel_J0_e(ctypes.c_double(x), ctypes.byref(result), ctypes.byref(error))

    if status != 0:
        raise RuntimeError(f"GSL function returned error code {status}")

    return GslSfResult(result.value, error.value)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python script.py <x>")
        sys.exit(1)

    x = float(sys.argv[1])
    result = compute_bessel_j0(x)
    print(result)

