import numpy as np

def cblas_ddot_wrapper(vector_x, vector_y):
    # Check if inputs are valid lists of floats
    if not isinstance(vector_x, list) or not isinstance(vector_y, list):
        raise ValueError("Inputs must be lists.")
    if not all(isinstance(x, (int, float)) for x in vector_x) or not all(isinstance(y, (int, float)) for y in vector_y):
        raise ValueError("All elements must be numeric.")
    if len(vector_x) != len(vector_y):
        raise ValueError("Vectors must be of the same length.")

    # Convert lists to numpy arrays
    n = len(vector_x)
    x = np.array(vector_x, dtype=np.float64)
    y = np.array(vector_y, dtype=np.float64)

    # Load the GSL libraries
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError:
        raise RuntimeError("Failed to load GSL libraries. Ensure they are installed and accessible.")

