class GslMultiset:
    _libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    _libgsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    _libgsl.gsl_multiset_alloc.argtypes = [ctypes.c_int, ctypes.c_int]
    _libgsl.gsl_multiset_alloc.restype = ctypes.POINTER(ctypes.c_void_p)

    def __init__(self, n, k):
        self._ptr = self.allocate_multiset(n, k)
        if not self._ptr:
            raise RuntimeError("Failed to allocate multiset")

    @classmethod
    def allocate_multiset(cls, n, k):
        result = cls._libgsl.gsl_multiset_alloc(n, k)
        if not result:
            raise RuntimeError("GSL multiset allocation failed")
        return result

if __name__ == "__main__":
    try:
        n = 10
        k = 3
        multiset = GslMultiset(n, k)
        print(f"Allocated multiset with n={n}, k={k}, pointer: {multiset._ptr}")
    except Exception as e:
